-- pup_camps | install.sql
-- Safe to run more than once. The resource also creates its own tables on start.
--
-- Owned tables: clan, wagon_stash
-- Shared table: cron_state (also used by pup_mercantile, pup_realestate, pup_ranchero)
-- Column owned on a shared table: characters.clan

CREATE TABLE IF NOT EXISTS `clan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `info` longtext NOT NULL DEFAULT '[]',
  `cash` tinytext NOT NULL DEFAULT 0,
  `inventory` longtext NOT NULL DEFAULT '[]',
  `invlimit` int(11) DEFAULT 1000,
  `repo` int(11) DEFAULT 0,
  `taxmoney` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `coords` (`id`),
  KEY `container` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `wagon_stash` (
  `charid` int(11) NOT NULL,
  `stash` longtext NULL,
  PRIMARY KEY (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `cron_state` (
  `name` varchar(64) NOT NULL,
  `lastrun` varchar(16) NOT NULL DEFAULT '',
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `characters` ADD COLUMN IF NOT EXISTS `clan` INT(11) NULL DEFAULT 0;

